python3 -c "
import json
with open('/app/resources/treasury_bulletin_1962_03.json') as f:
    data = json.load(f)

# Find keys related to ownership
def find_keys(d, path=''):
    if isinstance(d, dict):
        for k, v in d.items():
            if 'owner' in k.lower():
                print(f'{path}{k}')
            find_keys(v, path + k + '.')
    elif isinstance(d, list) and len(d) > 0:
        find_keys(d[0], path + '[].')

find_keys(data)
"
